# ---------------------------------------------------------------- helpers

def clean(fragment):
    txt = re.sub(r"<[^>]+>", " ", fragment or "")
    return re.sub(r"\s+", " ", html.unescape(txt)).strip()


def attr(value):
    return html.escape(value or "", quote=True)


def page_url(path):
    return SITE + "/" if path == "index.html" else SITE + "/" + path


def abs_asset(path, src):
    if src.startswith(("http://", "https://")):
        return src
    base = posixpath.dirname(path)
    return SITE + "/" + posixpath.normpath(posixpath.join(base, src)).lstrip("/")


def size_of(url):
    if url in _SIZES:
        return _SIZES[url]
    out = None
    if url.startswith(SITE + "/"):
        local = url[len(SITE) + 1:]
        if os.path.exists(local):
            try:
                from PIL import Image
                with Image.open(local) as im:
                    out = im.size
            except Exception:
                out = None
    _SIZES[url] = out
    return out


def head_title(src):
    m = re.search(r"<title>(.*?)</title>", src, re.S)
    return clean(m.group(1)) if m else ""


def head_desc(src):
    m = re.search(r'<meta name="description" content="(.*?)"\s*/?>', src, re.S)
    return clean(m.group(1)) if m else ""


def main_of(src):
    m = re.search(r"<main>(.*?)</main>", src, re.S)
    return m.group(1) if m else src


def page_image(path, src):
    body = main_of(src)
    for m in re.finditer(r"<img\b[^>]*>", body):
        tag = m.group(0)
        s = re.search(r'src="([^"]+)"', tag)
        if not s:
            continue
        url = s.group(1)
        if "/brand/" in url or url.endswith(".svg") or "logo" in url:
            continue
        a = re.search(r'alt="([^"]*)"', tag)
        return abs_asset(path, url), clean(a.group(1) if a else "")
    return SITE + "/" + DEFAULT_IMAGE, "CreArtBox in performance"


def h1_of(src, fallback=""):
    m = re.search(r"<h1[^>]*>(.*?)</h1>", src, re.S)
    return clean(m.group(1)) if m else fallback


def first_paragraph(src):
    body = main_of(src)
    for m in re.finditer(r"<p[^>]*>(.*?)</p>", body, re.S):
        txt = clean(m.group(1))
        if len(txt) > 60:
            return txt
    return ""


